This snippet shows how to use the  method to create an instance that implements the controller API client.

var serviceClient = ClientFactory.GetServiceApiClientV1("My App Name");
var chassisGuid = (await serviceClient.ListChassis()).First().ChassisGuid;
var controllerGuid = (await serviceClient.ListControllers(chassisGuid)).First().ControllerGuid;
var controllerClient = await ClientFactory.GetControllerApiClientV1(serviceClient, controllerGuid);

