This snippet shows how to use the  method to write values to multiple tags.

var serviceClient = ClientFactory.GetServiceApiClientV1("My App Name");
var chassisGuid = (await serviceClient.ListChassis()).First().ChassisGuid;
var controllerGuid = (await serviceClient.ListControllers(chassisGuid)).First().ControllerGuid;
var controllerClient = await ClientFactory.GetControllerApiClientV1(serviceClient, controllerGuid);
var tagHandle1 = await controllerClient.RegisterTag("tag_specifier_1"​);
var tagHandle2 = await controllerClient.RegisterTag("tag_specifier_2"​);
var tagHandle1Bytes = System.BitConverter.GetBytes(tagHandle1).Reverse().ToArray();
var tagHandle2Bytes = System.BitConverter.GetBytes(tagHandle2).Reverse().ToArray();
var data = await controllerClient.WriteTags(
    new byte[] { tagHandle1Bytes[0], tagHandle1Bytes[1], tagHandle1Bytes[2], tagHandle1Bytes[3],
        0, 0, 0, 4,
        45, 65, 71, 2,
        tagHandle2Bytes[0], tagHandle2Bytes[1], tagHandle2Bytes[2], tagHandle2Bytes[3],
        0, 0, 0, 1,
        6
});

