This snippet shows how to use the  method to create a new controller instance.

var client = ClientFactory.GetServiceApiClientV1("My App Name");
var chassisGuid = (await client.ListChassis()).First().ChassisGuid;
var firmwareGuid = (await client.ListFirmwarePackages()).First().Uuid;
var update = new ControllerUpdate
{
    FirmwarePackageGuid = firmwareGuid,
    Name = "my_controller",
    Description = "A controller.",
    ChassisGuid = chassisGuid,
    Slot = 0,
    IPConfigurationData = new IP4ConfigurationData
    {
        Address = IPAddress.Parse("127.0.0.1"),
        Netmask = IPAddress.Parse("255.255.255.0")
    },
    KeySwitchPosition = KeySwitchPosition.Remote,
    IsEnabled = true,
    IsSdCardAttached = false,
    ProjectPath = "C:\\users\\username\\projects\\project.ACD"
};
var controller = await client.CreateController(update);

This snippet shows how to use the  method to create a new controller.

var client = ClientFactory.GetServiceApiClientV1("My App Name");
var acdPath = "C:\\users\\username\\projects\\project.ACD";
using (var fileHandle = await client.SendFile(acdPath))
{
    var controllerUpdate = await client.GetControllerInfoFromAcd(fileHandle);
    var controllerData = await client.CreateController(controllerUpdate);
}

